// AC Display — Propostas Comerciais v4.0
// Backend: Node.js/Express + JSON local (sem Supabase)

// ─── Logo (base64) ────────────────────────────────────────────────────────────
const LOGO_BASE64 = "";

// ─── Estado Global ────────────────────────────────────────────────────────────
let currentUser = null;
let authToken   = localStorage.getItem('auth_token') || null;
let isSignUpMode = false;

let LEASING_FACTORS = {
  ti:         { "12": 0.0791, "24": 0.0719, "36": 0.0654, "48": 0.0556 },
  impressao:  { "12": 0.0990, "24": 0.0900, "36": 0.0820, "48": 0.0740 }
};
let SALE_FACTOR = parseFloat(localStorage.getItem('factor_sale')) || 2.04;

let currentProposalItems = [];
let allProducts = [];
let allProposals = [];

// ─── API Helper ───────────────────────────────────────────────────────────────
async function api(method, path, body) {
  const opts = {
    method,
    headers: { 'Content-Type': 'application/json' }
  };
  if (authToken) opts.headers['Authorization'] = 'Bearer ' + authToken;
  if (body)      opts.body = JSON.stringify(body);
  const res = await fetch('/api' + path, opts);
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Erro na requisição');
  return data;
}

// ─── Toast ────────────────────────────────────────────────────────────────────
function showToast(msg, type = 'success') {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = 'toast toast-' + type;
  toast.textContent = msg;
  container.appendChild(toast);
  requestAnimationFrame(() => toast.classList.add('show'));
  setTimeout(() => {
    toast.classList.remove('show');
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// ─── Navigation ───────────────────────────────────────────────────────────────
function navigate(viewId) {
  document.querySelectorAll('section[id^="view-"]').forEach(s => s.classList.add('hidden'));
  const target = document.getElementById('view-' + viewId);
  if (target) target.classList.remove('hidden');

  if (viewId === 'products' || viewId === 'proposals') loadProducts();
  if (viewId === 'history')   loadProposals();
  if (viewId === 'proposals') updateProposalNumber();
  if (viewId === 'settings')  loadConfiguredFactors();
}
window.navigate = navigate;

// ─── Auth ─────────────────────────────────────────────────────────────────────
function toggleAuthMode() {
  isSignUpMode = !isSignUpMode;
  document.getElementById('auth-title').textContent     = isSignUpMode ? 'Criar Conta' : 'Fazer Login';
  document.getElementById('auth-subtitle').textContent  = isSignUpMode ? 'Cadastre-se rapidamente com e-mail e senha' : 'Insira suas credenciais para continuar';
  document.getElementById('btn-auth-submit').textContent = isSignUpMode ? 'Registrar-se' : 'Entrar';
  document.getElementById('auth-switch-text').textContent = isSignUpMode ? 'Já possui uma conta?' : 'Não tem uma conta?';
  document.getElementById('auth-switch-link').textContent = isSignUpMode ? 'Fazer Login' : 'Cadastre-se';
}

async function handleAuthSubmit(e) {
  e.preventDefault();
  const email    = document.getElementById('auth-email').value.trim();
  const password = document.getElementById('auth-password').value;
  const btn      = document.getElementById('btn-auth-submit');
  const orig     = btn.textContent;
  btn.disabled   = true;
  btn.innerHTML  = '<span class="spinner"></span> Processando...';

  try {
    const path = isSignUpMode ? '/auth/register' : '/auth/login';
    const data = await api('POST', path, { email, password });
    authToken   = data.token;
    currentUser = data.user;
    localStorage.setItem('auth_token', authToken);
    document.getElementById('display-user-email').textContent = currentUser.email;
    showToast(isSignUpMode ? 'Conta criada com sucesso!' : 'Login efetuado!', 'success');
    navigate('dashboard');
  } catch (err) {
    showToast(err.message, 'error');
  } finally {
    btn.disabled   = false;
    btn.textContent = orig;
  }
}

async function handleLogout() {
  authToken   = null;
  currentUser = null;
  localStorage.removeItem('auth_token');
  showToast('Sessão encerrada.', 'success');
  navigate('auth');
}

async function checkSession() {
  if (!authToken) return navigate('auth');
  try {
    const data  = await api('GET', '/auth/me');
    currentUser = data.user;
    document.getElementById('display-user-email').textContent = currentUser.email;
    navigate('dashboard');
  } catch {
    authToken = null;
    localStorage.removeItem('auth_token');
    navigate('auth');
  }
}

// ─── Produtos ─────────────────────────────────────────────────────────────────
async function loadProducts() {
  const tableBody = document.getElementById('products-table-body');
  if (tableBody) tableBody.innerHTML = '<tr><td colspan="3" class="text-center"><span class="spinner"></span> Carregando...</td></tr>';
  try {
    allProducts = await api('GET', '/produtos');
    renderProductsTable();
  } catch (err) {
    showToast('Erro ao carregar produtos: ' + err.message, 'error');
    if (tableBody) tableBody.innerHTML = '<tr><td colspan="3" class="text-center">Erro ao carregar produtos.</td></tr>';
  }
}

function renderProductsTable(products = null) {
  const tableBody = document.getElementById('products-table-body');
  if (!tableBody) return;

  const searchInput = document.getElementById('prod-search-input');
  const query = searchInput ? searchInput.value.toLowerCase().trim() : '';

  const list = products !== null ? products : (
    query ? allProducts.filter(p => p.nome.toLowerCase().includes(query)) : allProducts
  );

  const countLabel = document.getElementById('products-count-label');
  if (countLabel) {
    if (allProducts.length === 0) {
      countLabel.textContent = 'Nenhum produto cadastrado no momento.';
    } else if (query) {
      countLabel.textContent = `${list.length} de ${allProducts.length} produto(s) encontrado(s) para "${query}"`;
    } else {
      countLabel.textContent = `Total de ${allProducts.length} produto(s) cadastrado(s)`;
    }
  }

  if (list.length === 0) {
    const msg = query 
      ? `Nenhum produto encontrado para "<strong>${query}</strong>".`
      : 'Nenhum produto cadastrado.';
    tableBody.innerHTML = `<tr><td colspan="3" class="text-center" style="color:var(--text-secondary);padding:24px">${msg}</td></tr>`;
    return;
  }

  tableBody.innerHTML = list.map(p => {
    const price = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(p.preco);
    const escapedNome = p.nome.replace(/"/g, '&quot;');
    return `<tr>
      <td style="font-weight:500;">${p.nome}</td>
      <td style="text-align:right;font-weight:700;color:var(--cyan);white-space:nowrap;">${price}</td>
      <td style="text-align:center;white-space:nowrap;">
        <button type="button" class="btn-edit-item" data-id="${p.id}" data-nome="${escapedNome}" data-preco="${p.preco}">Editar</button>
        <button type="button" class="btn-delete-item" data-id="${p.id}" data-nome="${escapedNome}">Excluir</button>
      </td>
    </tr>`;
  }).join('');
}

function openEditProductModal(id, nome, preco) {
  const modal = document.getElementById('modal-edit-product');
  if (!modal) return;
  document.getElementById('edit-prod-id').value = id;
  document.getElementById('edit-prod-name').value = nome;
  document.getElementById('edit-prod-price').value = preco;
  modal.classList.remove('hidden');
  setTimeout(() => document.getElementById('edit-prod-name').focus(), 100);
}

function closeEditProductModal() {
  const modal = document.getElementById('modal-edit-product');
  if (modal) modal.classList.add('hidden');
}

async function handleEditProductSubmit(e) {
  e.preventDefault();
  const id    = document.getElementById('edit-prod-id').value;
  const name  = document.getElementById('edit-prod-name').value.trim();
  const price = parseFloat(document.getElementById('edit-prod-price').value);

  if (!name) { showToast('Informe o nome do produto.', 'error'); return; }
  if (isNaN(price) || price < 0) { showToast('Preço inválido.', 'error'); return; }

  const btn = document.getElementById('btn-save-edit-product');
  const orig = btn.textContent;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span> Salvando...';

  try {
    const updated = await api('PUT', '/produtos/' + id, { nome: name, preco: price });
    const idx = allProducts.findIndex(p => p.id === id);
    if (idx !== -1) {
      allProducts[idx].nome = updated.nome;
      allProducts[idx].preco = updated.preco;
    }
    showToast(`Produto "${name}" atualizado com sucesso!`, 'success');
    closeEditProductModal();
    renderProductsTable();
  } catch (err) {
    showToast('Erro ao atualizar produto: ' + err.message, 'error');
  } finally {
    btn.disabled = false;
    btn.textContent = orig;
  }
}

async function handleDeleteProduct(id, nome) {
  if (!confirm(`Deseja realmente excluir o produto "${nome}"?`)) return;
  try {
    await api('DELETE', '/produtos/' + id);
    allProducts = allProducts.filter(p => p.id !== id);
    showToast(`Produto "${nome}" excluído com sucesso!`, 'success');
    renderProductsTable();
  } catch (err) {
    showToast('Erro ao excluir: ' + err.message, 'error');
  }
}

async function handleProductSubmit(e) {
  e.preventDefault();
  const name  = document.getElementById('prod-name').value.trim();
  const price = parseFloat(document.getElementById('prod-price').value);
  if (isNaN(price) || price < 0) { showToast('Preço inválido.', 'error'); return; }
  try {
    await api('POST', '/produtos', { nome: name, preco: price });
    showToast(`Produto "${name}" cadastrado!`, 'success');
    document.getElementById('product-form').reset();
    loadProducts();
  } catch (err) {
    showToast('Erro ao cadastrar: ' + err.message, 'error');
  }
}

// ─── Planilha ─────────────────────────────────────────────────────────────────
function processSpreadsheet(file) {
  const reader = new FileReader();
  reader.onload = async function(e) {
    try {
      const data     = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: 'array' });
      const sheet    = workbook.Sheets[workbook.SheetNames[0]];
      const json     = XLSX.utils.sheet_to_json(sheet, { header: 1 });
      if (json.length < 2) { showToast('Planilha vazia ou sem cabeçalhos.', 'error'); return; }

      const headers    = json[0].map(h => String(h).toLowerCase().trim());
      const nameKw     = ['produto','nome','product','name','descrição','descricao'];
      const priceKw    = ['preço','preco','price','valor','value','custo'];
      let nameCol  = headers.findIndex(h => nameKw.some(k => h.includes(k)));
      let priceCol = headers.findIndex(h => priceKw.some(k => h.includes(k)));
      if (nameCol  === -1) nameCol  = 0;
      if (priceCol === -1) priceCol = 1;

      const items = [];
      for (let i = 1; i < json.length; i++) {
        const row = json[i];
        if (!row[nameCol]) continue;
        const raw = row[priceCol];
        let p = 0;
        if (typeof raw === 'number') { p = raw; }
        else if (raw != null) { p = parseFloat(String(raw).replace(/[R$\s]/g,'').replace(/\./g,'').replace(',','.')); }
        items.push({ nome: String(row[nameCol]).trim(), preco: isNaN(p) ? 0 : p });
      }
      if (items.length === 0) { showToast('Nenhum produto válido na planilha.', 'error'); return; }

      await api('POST', '/produtos', items);
      showToast(`${items.length} produtos importados!`, 'success');
      document.getElementById('dropzone').classList.remove('dragover');
      document.getElementById('file-info-container').classList.add('hidden');
      loadProducts();
    } catch (err) {
      showToast('Erro ao processar planilha: ' + err.message, 'error');
    }
  };
  reader.readAsArrayBuffer(file);
}

// ─── Proposta ─────────────────────────────────────────────────────────────────
function updateProposalNumber() {
  const now = new Date();
  const num = String(now.getFullYear()).slice(2) + String(now.getMonth()+1).padStart(2,'0') + String(now.getDate()).padStart(2,'0') + String(now.getHours()).padStart(2,'0') + String(now.getMinutes()).padStart(2,'0');
  const el = document.getElementById('proposal-form-title');
  if (el) el.innerHTML = 'Criar Proposta <span style="font-size:0.9rem;font-weight:normal;color:var(--cyan);margin-left:10px">(Nº ' + num + ')</span>';
}

function renderProposalItems() {
  const tbody = document.getElementById('proposal-items-body');
  if (!tbody) return;
  if (currentProposalItems.length === 0) {
    tbody.innerHTML = '<tr><td colspan="3" class="text-center" style="color:var(--text-secondary);padding:20px">Nenhum produto adicionado.</td></tr>';
    return;
  }
  tbody.innerHTML = currentProposalItems.map((item, i) => {
    const fmtPrice = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(item.preco);
    return `<tr>
      <td>${item.nome}</td>
      <td style="text-align:center">${item.qty}</td>
      <td style="text-align:center">
        <button type="button" class="btn-delete-item" data-index="${i}" style="padding:4px 10px;font-size:0.8rem">Remover</button>
      </td>
    </tr>`;
  }).join('');
}

function computeSimulation() {
  const isImpressao  = document.getElementById('switch-factor-type').checked;
  const factors      = isImpressao ? LEASING_FACTORS.impressao : LEASING_FACTORS.ti;
  const isSaleOn     = document.getElementById('switch-sale-enabled').checked;
  const terms        = ['12','24','36','48'];
  const switches     = terms.map(t => document.getElementById('switch-' + t + 'm'));

  let totalCost = 0;
  currentProposalItems.forEach(item => { totalCost += item.preco * item.qty; });

  const activeTerms = [];
  terms.forEach((t, idx) => {
    if (switches[idx] && switches[idx].checked) {
      const val = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(totalCost * (factors[t] || 0));
      activeTerms.push({ name: t + ' Meses', val });
    }
  });

  const resultsSection = document.getElementById('simulation-results-section');
  const resultsCards   = document.getElementById('simulation-results-cards');
  if (activeTerms.length > 0 && totalCost > 0) {
    resultsSection.classList.remove('hidden');
    resultsCards.innerHTML = activeTerms.map(t =>
      `<div class="switch-card" style="flex-direction:column;gap:4px;padding:16px">
         <span style="font-size:0.8rem;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.5px">${t.name}</span>
         <span style="font-size:1.4rem;font-weight:800;color:var(--cyan)">${t.val}</span>
         <span style="font-size:0.75rem;color:var(--text-secondary)">/ mês</span>
       </div>`
    ).join('');
  } else {
    if (resultsSection) resultsSection.classList.add('hidden');
  }

  return { totalCost, activeTerms, isSaleOn, factors };
}

async function handleProposalSubmit(e) {
  e.preventDefault();
  if (currentProposalItems.length === 0) { showToast('Adicione pelo menos um produto.', 'error'); return; }

  const client  = document.getElementById('prop-client-name').value.trim();
  const cnpj    = document.getElementById('prop-cnpj').value.trim();
  const service = document.getElementById('prop-service').value.trim();
  const now     = new Date();
  const dateStr = now.toLocaleDateString('pt-BR');
  const num     = String(now.getFullYear()).slice(2) + String(now.getMonth()+1).padStart(2,'0') + String(now.getDate()).padStart(2,'0') + String(now.getHours()).padStart(2,'0') + String(now.getMinutes()).padStart(2,'0');

  const { totalCost, activeTerms, isSaleOn } = computeSimulation();
  const opcoesComerciais = {
    venda_direta: {
      habilitado: isSaleOn,
      valor: isSaleOn ? new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(totalCost * SALE_FACTOR) : ''
    },
    locacao: activeTerms
  };

  const proposalData = {
    numero:            num,
    cliente:           client,
    cnpj,
    servico:           service,
    itens:             currentProposalItems.map(i => ({ nome: i.nome, qty: i.qty })),
    opcoes_comerciais: opcoesComerciais,
    data_emissao:      dateStr
  };

  try {
    await api('POST', '/propostas', proposalData);
    showToast('Proposta salva no histórico!', 'success');
  } catch (err) {
    showToast('Proposta gerada (não salva): ' + err.message, 'error');
  }

  generateProposalPDF(proposalData);
  document.getElementById('proposal-form').reset();
  currentProposalItems = [];
  renderProposalItems();
  document.getElementById('simulation-results-section').classList.add('hidden');
}

// ─── PDF ──────────────────────────────────────────────────────────────────────
function generateProposalPDF(proposal) {
  const { jsPDF } = window.jspdf;
  const doc      = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const pageW    = doc.internal.pageSize.getWidth();
  const pageH    = doc.internal.pageSize.getHeight();
  const margin   = 15;
  const contentW = pageW - margin * 2;
  let y          = margin;

  function hexRGB(hex) { return [parseInt(hex.slice(1,3),16), parseInt(hex.slice(3,5),16), parseInt(hex.slice(5,7),16)]; }
  function setTxt(h) { doc.setTextColor(...hexRGB(h)); }
  function setFill(h) { doc.setFillColor(...hexRGB(h)); }
  function setDraw(h) { doc.setDrawColor(...hexRGB(h)); }
  function checkPage(n) { if (y + n > pageH - margin) { doc.addPage(); y = margin; } }

  // Header
  try {
    setFill('#0a1128');
    doc.roundedRect(margin, y, 62, 22, 2, 2, 'F');
    doc.addImage('data:image/png;base64,' + LOGO_BASE64, 'PNG', margin + 3, y + 2, 56, 18);
  } catch {}
  doc.setFontSize(7); doc.setFont('helvetica','bold'); setTxt('#666666');
  doc.text('PROPOSTA COMERCIAL', pageW - margin, y + 5, { align: 'right' });
  doc.setFontSize(14); doc.setFont('helvetica','bold'); setTxt('#ff007f');
  doc.text('Nº ' + proposal.numero, pageW - margin, y + 12, { align: 'right' });
  doc.setFontSize(7); doc.setFont('helvetica','normal'); setTxt('#888888');
  doc.text('Emissão: ' + proposal.data_emissao, pageW - margin, y + 17, { align: 'right' });
  y += 27;
  setDraw('#0a1128'); doc.setLineWidth(0.5);
  doc.line(margin, y, pageW - margin, y); y += 7;

  // Client
  doc.setFontSize(9); doc.setFont('helvetica','bold'); setTxt('#0a1128');
  doc.text('DADOS DO CLIENTE', margin, y); y += 5;
  [['Cliente:', proposal.cliente], ['CNPJ:', proposal.cnpj], ['Serviço:', proposal.servico]].forEach(([lbl, val], i) => {
    checkPage(9);
    setFill(i % 2 === 0 ? '#fafbfc' : '#f0f4f8'); doc.rect(margin, y - 4, contentW, 8, 'F');
    setDraw('#e0e0e0'); doc.setLineWidth(0.2); doc.rect(margin, y - 4, contentW, 8, 'D');
    doc.setFontSize(8); doc.setFont('helvetica','bold'); setTxt('#555555'); doc.text(lbl, margin + 3, y + 1);
    doc.setFont('helvetica','normal'); setTxt('#0a1128');
    doc.text(doc.splitTextToSize(String(val || ''), contentW - 36), margin + 36, y + 1);
    y += 8;
  });
  y += 6;

  // Items
  checkPage(20);
  doc.setFontSize(9); doc.setFont('helvetica','bold'); setTxt('#0a1128');
  doc.text('PRODUTOS / DESCRIÇÃO', margin, y);
  doc.text('QTD', pageW - margin, y, { align: 'right' }); y += 3;
  setDraw('#0a1128'); doc.setLineWidth(0.4); doc.line(margin, y, pageW - margin, y); y += 5;
  proposal.itens.forEach((item, i) => {
    checkPage(9);
    setDraw('#e0e0e0'); doc.setLineWidth(0.1); doc.line(margin, y + 4, pageW - margin, y + 4);
    doc.setFontSize(8); doc.setFont('helvetica','normal'); setTxt('#333333');
    doc.text(doc.splitTextToSize(String(item.nome || ''), contentW - 26), margin + 3, y + 1);
    doc.setFont('helvetica','bold'); setTxt('#0a1128');
    doc.text(String(item.qty || ''), pageW - margin - 3, y + 1, { align: 'right' }); y += 8;
  });
  y += 8;

  // Commercial
  const opcoes = proposal.opcoes_comerciais;
  checkPage(20); doc.setFontSize(9); doc.setFont('helvetica','bold'); setTxt('#0a1128');
  doc.text('CONDIÇÕES COMERCIAIS PROPOSTAS', margin, y); y += 6;

  if (opcoes && opcoes.locacao && opcoes.locacao.length > 0) {
    const n = opcoes.locacao.length, cols = Math.min(n, 4), rows = Math.ceil(n / cols);
    const blockH = 14 + rows * 18;
    checkPage(blockH + 10);
    setFill('#fafbfc'); doc.rect(margin, y - 2, contentW, blockH, 'F');
    setDraw('#e0e0e0'); doc.setLineWidth(0.2); doc.rect(margin, y - 2, contentW, blockH, 'D');
    doc.setFontSize(8); doc.setFont('helvetica','bold'); setTxt('#0088cc');
    doc.text('OPÇÃO DE LOCAÇÃO MENSAL (OUTSOURCING)', margin + 4, y + 3); y += 9;
    const colW = contentW / cols;
    opcoes.locacao.forEach((t, i) => {
      const col = i % cols, row = Math.floor(i / cols);
      const cx = margin + col * colW, cy = y + row * 18;
      setFill('#e8f4fb'); doc.rect(cx + 2, cy - 2, colW - 4, 15, 'F');
      setDraw('#00aacc'); doc.setLineWidth(0.4); doc.line(cx + 2, cy - 2, cx + colW - 2, cy - 2);
      doc.setFontSize(6.5); doc.setFont('helvetica','bold'); setTxt('#666666'); doc.text(String(t.name), cx + colW/2, cy + 2, { align: 'center' });
      doc.setFontSize(10); doc.setFont('helvetica','bold'); setTxt('#0a1128'); doc.text(String(t.val), cx + colW/2, cy + 8, { align: 'center' });
      doc.setFontSize(6); doc.setFont('helvetica','normal'); setTxt('#0088cc'); doc.text('/ mês', cx + colW/2, cy + 11.5, { align: 'center' });
    });
    y += rows * 18 + 2;
    const note = doc.splitTextToSize('* Valores mensais fixos. Inclui suporte, substituição rápida (SLA) e assistência técnica integral.', contentW - 6);
    doc.setFontSize(7); doc.setFont('helvetica','normal'); setTxt('#666666'); doc.text(note, margin + 4, y); y += note.length * 3.5 + 4;
  }

  if (opcoes && opcoes.venda_direta && opcoes.venda_direta.habilitado) {
    const valorStr = String(opcoes.venda_direta.valor || '');
    const valorNum = parseFloat(valorStr.replace(/[R$\s.]/g,'').replace(',','.')) || 0;
    const parcelaStr = (valorNum / 12).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const halfW = (contentW - 4) / 2;
    checkPage(30);
    setFill('#fcf0f7'); doc.rect(margin, y - 2, halfW, 27, 'F');
    setDraw('#ff007f'); doc.setLineWidth(1); doc.line(margin, y - 2, margin, y + 25); doc.setLineWidth(0.2);
    doc.setFontSize(7.5); doc.setFont('helvetica','bold'); setTxt('#ff007f');
    doc.text('OPÇÃO DE VENDA À VISTA', margin + 4, y + 3);
    doc.setFontSize(14); doc.setFont('helvetica','bold'); setTxt('#0a1128'); doc.text(valorStr, margin + 4, y + 13);
    doc.setFontSize(6.5); doc.setFont('helvetica','normal'); setTxt('#666666');
    doc.text('* Pagamento único à vista.', margin + 4, y + 20);
    doc.text('Equipamentos do cliente.', margin + 4, y + 24);
    const bx = margin + halfW + 4;
    setFill('#fff8f0'); doc.rect(bx, y - 2, halfW, 27, 'F');
    setDraw('#ff8c00'); doc.setLineWidth(1); doc.line(bx, y - 2, bx, y + 25); doc.setLineWidth(0.2);
    doc.setFontSize(7.5); doc.setFont('helvetica','bold'); setTxt('#ff8c00');
    doc.text('OPÇÃO PARCELADO EM 12x NO CARTÃO', bx + 4, y + 3);
    doc.setFontSize(10); doc.setFont('helvetica','bold'); setTxt('#0a1128'); doc.text('12x de ' + parcelaStr, bx + 4, y + 13);
    doc.setFontSize(6.5); doc.setFont('helvetica','normal'); setTxt('#666666');
    doc.text('* Parcelado no cartão de crédito.', bx + 4, y + 20);
    doc.text('Total: ' + valorStr, bx + 4, y + 24); y += 31;
  }

  // Conditions
  checkPage(40); y += 4;
  doc.setFontSize(8.5); doc.setFont('helvetica','bold'); setTxt('#0a1128');
  doc.text('OBSERVAÇÕES E CONDIÇÕES GERAIS', margin, y); y += 5;
  ['Validade desta proposta: 10 (dez) dias corridos a contar da data de emissão.',
   'Prazo de entrega e início da operação: a combinar conforme cronograma técnico da contratada.',
   'Para a opção de locação, a manutenção corretiva e preventiva está integralmente coberta por nossa equipe.',
   'O fornecimento de infraestrutura elétrica e pontos de rede é de responsabilidade do cliente contratante.'
  ].forEach(c => {
    checkPage(8); doc.setFontSize(7.5); doc.setFont('helvetica','normal'); setTxt('#555555');
    const lns = doc.splitTextToSize('• ' + c, contentW - 4); doc.text(lns, margin + 3, y); y += lns.length * 3.8 + 2;
  });

  // Signatures
  checkPage(25); y += 12;
  const sigW = contentW * 0.42;
  setDraw('#888888'); doc.setLineWidth(0.3);
  doc.line(margin, y, margin + sigW, y); doc.line(pageW - margin - sigW, y, pageW - margin, y); y += 4;
  doc.setFontSize(8); doc.setFont('helvetica','bold'); setTxt('#0a1128');
  doc.text('AC DISPLAY', margin + sigW/2, y, { align: 'center' });
  doc.text('De Acordo: ' + proposal.cliente, pageW - margin - sigW/2, y, { align: 'center' }); y += 4;
  doc.setFontSize(7); doc.setFont('helvetica','normal'); setTxt('#666666');
  doc.text('Departamento Comercial', margin + sigW/2, y, { align: 'center' });
  doc.text('Assinatura e Carimbo (Responsável)', pageW - margin - sigW/2, y, { align: 'center' });

  doc.save('proposta_ACDisplay_N' + proposal.numero + '_' + proposal.cliente.replace(/\s+/g,'_') + '.pdf');
  showToast('Proposta Nº ' + proposal.numero + ' gerada!', 'success');
}

// ─── Histórico ────────────────────────────────────────────────────────────────
async function loadProposals() {
  const tbody = document.getElementById('history-table-body');
  if (tbody) tbody.innerHTML = '<tr><td colspan="5" class="text-center"><span class="spinner"></span> Carregando...</td></tr>';
  const search = document.getElementById('history-search');
  if (search) search.value = '';
  try {
    allProposals = await api('GET', '/propostas');
    renderProposalsTable(allProposals);
  } catch (err) {
    showToast('Erro ao carregar histórico: ' + err.message, 'error');
  }
}

let viewingProposal = null;

function renderProposalsTable(proposals) {
  const tbody = document.getElementById('history-table-body');
  if (!tbody) return;
  if (proposals.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5" class="text-center" style="color:var(--text-secondary);padding:30px">Nenhuma proposta encontrada.</td></tr>';
    return;
  }
  tbody.innerHTML = proposals.map((p) => `
    <tr>
      <td>${p.data_emissao}</td>
      <td style="text-align:center;font-weight:700;color:var(--cyan)">Nº ${p.numero}</td>
      <td style="font-weight:600">${p.cliente}</td>
      <td style="font-style:italic;color:var(--text-secondary)">${p.servico}</td>
      <td style="text-align:center;white-space:nowrap;">
        <button type="button" class="btn-view-proposal" data-id="${p.id}" title="Visualizar Proposta">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
            <circle cx="12" cy="12" r="3"></circle>
          </svg>
        </button>
        <button type="button" class="btn-download-pdf" data-id="${p.id}">PDF</button>
        <button type="button" class="btn-delete-item" data-id="${p.id}">Excluir</button>
      </td>
    </tr>
  `).join('');
}

function openProposalModal(proposal) {
  if (!proposal) return;
  viewingProposal = proposal;

  const modal = document.getElementById('modal-view-proposal');
  if (!modal) return;

  document.getElementById('view-prop-title').textContent = 'Proposta Comercial';
  document.getElementById('view-prop-badge').textContent = 'Nº ' + proposal.numero;
  document.getElementById('view-prop-date').textContent = 'Emissão: ' + (proposal.data_emissao || '-');

  // Client info
  document.getElementById('view-prop-client').textContent = proposal.cliente || '-';
  document.getElementById('view-prop-cnpj').textContent = proposal.cnpj || '-';
  document.getElementById('view-prop-service').textContent = proposal.servico || '-';

  // Items
  const itemsBody = document.getElementById('view-prop-items-body');
  if (itemsBody) {
    if (!proposal.itens || proposal.itens.length === 0) {
      itemsBody.innerHTML = '<tr><td colspan="2" class="text-center" style="color:var(--text-secondary);padding:16px">Nenhum item listado</td></tr>';
    } else {
      itemsBody.innerHTML = proposal.itens.map(item => `
        <tr>
          <td>${item.nome}</td>
          <td style="text-align:center;font-weight:700;">${item.qty}</td>
        </tr>
      `).join('');
    }
  }

  // Commercial options
  const opcoes = proposal.opcoes_comerciais || {};
  
  // Locação
  const locacaoSection = document.getElementById('view-prop-locacao-section');
  const locacaoCards = document.getElementById('view-prop-locacao-cards');
  if (opcoes.locacao && opcoes.locacao.length > 0) {
    locacaoSection.classList.remove('hidden');
    locacaoCards.innerHTML = opcoes.locacao.map(t => `
      <div class="switch-card" style="flex-direction:column;gap:4px;padding:12px;text-align:center;justify-content:center;">
        <span style="font-size:0.75rem;color:var(--text-secondary);text-transform:uppercase;letter-spacing:0.5px">${t.name}</span>
        <span style="font-size:1.15rem;font-weight:800;color:var(--cyan)">${t.val}</span>
        <span style="font-size:0.7rem;color:var(--text-secondary)">/ mês</span>
      </div>
    `).join('');
  } else {
    locacaoSection.classList.add('hidden');
  }

  // Venda direta
  const vendaSection = document.getElementById('view-prop-venda-section');
  if (opcoes.venda_direta && opcoes.venda_direta.habilitado) {
    vendaSection.classList.remove('hidden');
    const valorStr = String(opcoes.venda_direta.valor || '');
    const valorNum = parseFloat(valorStr.replace(/[R$\s.]/g,'').replace(',','.')) || 0;
    const parcelaStr = (valorNum / 12).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    document.getElementById('view-prop-venda-vista').textContent = valorStr;
    document.getElementById('view-prop-venda-parcelado').textContent = '12x de ' + parcelaStr;
  } else {
    vendaSection.classList.add('hidden');
  }

  modal.classList.remove('hidden');
}

function closeProposalModal() {
  const modal = document.getElementById('modal-view-proposal');
  if (modal) modal.classList.add('hidden');
}

async function deleteProposal(id) {
  try {
    await api('DELETE', '/propostas/' + id);
    showToast('Proposta excluída.', 'success');
    loadProposals();
  } catch (err) {
    showToast('Erro ao excluir: ' + err.message, 'error');
  }
}

// ─── Fatores ──────────────────────────────────────────────────────────────────
function loadConfiguredFactors() {
  const storedTi  = localStorage.getItem('factors_ti');
  const storedImp = localStorage.getItem('factors_imp');
  const storedSale = localStorage.getItem('factor_sale');
  const dTi  = { "12": 0.0791, "24": 0.0719, "36": 0.0654, "48": 0.0556 };
  const dImp = { "12": 0.0990, "24": 0.0900, "36": 0.0820, "48": 0.0740 };
  LEASING_FACTORS.ti        = storedTi  ? { ...dTi,  ...JSON.parse(storedTi)  } : { ...dTi  };
  LEASING_FACTORS.impressao = storedImp ? { ...dImp, ...JSON.parse(storedImp) } : { ...dImp };
  SALE_FACTOR = storedSale ? parseFloat(storedSale) : 2.04;

  const map = [
    { id: 'factor-ti-12m',  v: LEASING_FACTORS.ti["12"]        },
    { id: 'factor-ti-24m',  v: LEASING_FACTORS.ti["24"]        },
    { id: 'factor-ti-36m',  v: LEASING_FACTORS.ti["36"]        },
    { id: 'factor-ti-48m',  v: LEASING_FACTORS.ti["48"]        },
    { id: 'factor-imp-12m', v: LEASING_FACTORS.impressao["12"] },
    { id: 'factor-imp-24m', v: LEASING_FACTORS.impressao["24"] },
    { id: 'factor-imp-36m', v: LEASING_FACTORS.impressao["36"] },
    { id: 'factor-imp-48m', v: LEASING_FACTORS.impressao["48"] },
    { id: 'factor-sale',    v: SALE_FACTOR                     }
  ];
  map.forEach(({ id, v }) => { const el = document.getElementById(id); if (el) el.value = v; });
}

function handleSettingsSubmit(e) {
  e.preventDefault();
  const newTi = {
    "12": parseFloat(document.getElementById('factor-ti-12m').value)  || 0.0791,
    "24": parseFloat(document.getElementById('factor-ti-24m').value)  || 0.0719,
    "36": parseFloat(document.getElementById('factor-ti-36m').value)  || 0.0654,
    "48": parseFloat(document.getElementById('factor-ti-48m').value)  || 0.0556
  };
  const newImp = {
    "12": parseFloat(document.getElementById('factor-imp-12m').value) || 0.0990,
    "24": parseFloat(document.getElementById('factor-imp-24m').value) || 0.0900,
    "36": parseFloat(document.getElementById('factor-imp-36m').value) || 0.0820,
    "48": parseFloat(document.getElementById('factor-imp-48m').value) || 0.0740
  };
  const newSale = parseFloat(document.getElementById('factor-sale').value) || 2.04;
  localStorage.setItem('factors_ti',  JSON.stringify(newTi));
  localStorage.setItem('factors_imp', JSON.stringify(newImp));
  localStorage.setItem('factor_sale', String(newSale));
  LEASING_FACTORS.ti        = newTi;
  LEASING_FACTORS.impressao = newImp;
  SALE_FACTOR               = newSale;
  showToast('Configurações salvas!', 'success');
  navigate('dashboard');
}

// ─── Eventos ──────────────────────────────────────────────────────────────────
function setupEvents() {
  function bind(id, ev, fn) {
    const el = document.getElementById(id);
    if (!el) return console.warn('Elemento não encontrado: #' + id);
    el.addEventListener(ev, fn);
  }

  bind('auth-switch-link', 'click', (e) => { e.preventDefault(); toggleAuthMode(); });
  bind('auth-form',        'submit', handleAuthSubmit);
  bind('btn-logout',       'click',  handleLogout);

  // Nav
  bind('card-products',  'click', () => navigate('products'));
  bind('card-proposals', 'click', () => navigate('proposals'));
  bind('btn-settings',   'click', () => navigate('settings'));
  bind('card-settings',  'click', () => navigate('settings'));
  bind('card-history',   'click', () => navigate('history'));

  // Products
  bind('product-form',        'submit', handleProductSubmit);
  bind('btn-refresh-products','click',  () => {
    const s = document.getElementById('prod-search-input');
    if (s) s.value = '';
    loadProducts();
  });

  // Search/consult products
  const prodSearch = document.getElementById('prod-search-input');
  if (prodSearch) {
    prodSearch.addEventListener('input', () => renderProductsTable());
  }

  // Edit / Delete buttons in products table
  const prodTableBody = document.getElementById('products-table-body');
  if (prodTableBody) {
    prodTableBody.addEventListener('click', (e) => {
      const editBtn = e.target.closest('.btn-edit-item');
      if (editBtn) {
        const id = editBtn.dataset.id;
        const prod = allProducts.find(p => p.id === id);
        if (prod) {
          openEditProductModal(prod.id, prod.nome, prod.preco);
        }
        return;
      }
      const delBtn = e.target.closest('.btn-delete-item');
      if (delBtn) {
        const id = delBtn.dataset.id;
        const prod = allProducts.find(p => p.id === id);
        if (prod) {
          handleDeleteProduct(prod.id, prod.nome);
        }
        return;
      }
    });
  }

  // Edit modal
  bind('edit-product-form', 'submit', handleEditProductSubmit);
  bind('btn-close-edit-modal', 'click', closeEditProductModal);
  bind('btn-cancel-edit-product', 'click', closeEditProductModal);

  const editModal = document.getElementById('modal-edit-product');
  if (editModal) {
    editModal.addEventListener('click', (e) => {
      if (e.target === editModal) closeEditProductModal();
    });
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeEditProductModal();
      closeProposalModal();
    }
  });

  // Dropzone
  const dz      = document.getElementById('dropzone');
  const fileInp = document.getElementById('file-input');
  const fileSel = document.getElementById('btn-select-file');
  if (dz) {
    dz.addEventListener('dragover', (e) => { e.preventDefault(); dz.classList.add('dragover'); });
    dz.addEventListener('dragleave', () => dz.classList.remove('dragover'));
    dz.addEventListener('drop', (e) => {
      e.preventDefault(); dz.classList.remove('dragover');
      const f = e.dataTransfer.files[0];
      if (f) { showFileInfo(f); processSpreadsheet(f); }
    });
  }
  if (fileSel && fileInp) {
    fileSel.addEventListener('click', () => fileInp.click());
    fileInp.addEventListener('change', (e) => {
      const f = e.target.files[0];
      if (f) { showFileInfo(f); processSpreadsheet(f); }
    });
  }

  function showFileInfo(file) {
    const ctn = document.getElementById('file-info-container');
    if (ctn) { ctn.classList.remove('hidden'); ctn.textContent = '📄 ' + file.name; }
  }

  // Proposal form
  bind('proposal-form', 'submit', handleProposalSubmit);

  const searchInput = document.getElementById('prop-product-search');
  const dropdown    = document.getElementById('prop-product-results');
  if (searchInput && dropdown) {
    searchInput.addEventListener('input', () => {
      const q = searchInput.value.toLowerCase().trim();
      if (!q) { dropdown.classList.add('hidden'); return; }
      const filtered = allProducts.filter(p => p.nome.toLowerCase().includes(q));
      if (filtered.length === 0) { dropdown.classList.add('hidden'); return; }
      dropdown.classList.remove('hidden');
      dropdown.innerHTML = filtered.slice(0, 10).map(p => {
        const price = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(p.preco);
        return `<div class="search-result-item" data-id="${p.id}" data-nome="${p.nome}" data-preco="${p.preco}">${p.nome} — ${price}</div>`;
      }).join('');
    });

    dropdown.addEventListener('click', (e) => {
      const item = e.target.closest('.search-result-item');
      if (!item) return;
      const hdn = document.getElementById('prop-selected-product-id');
      if (hdn) hdn.value = item.dataset.id;
      searchInput.value = item.dataset.nome;
      searchInput.dataset.preco = item.dataset.preco;
      dropdown.classList.add('hidden');
    });
  }

  bind('btn-add-item', 'click', () => {
    const hdn = document.getElementById('prop-selected-product-id');
    const id = hdn ? hdn.value : '';
    const name  = document.getElementById('prop-product-search').value.trim();
    const preco = parseFloat(document.getElementById('prop-product-search').dataset.preco || 0);
    const qty   = parseInt(document.getElementById('prop-quantity').value) || 1;
    if (!name) { showToast('Selecione um produto.', 'error'); return; }
    const existing = currentProposalItems.find(i => i.id === id && id !== '');
    if (existing) { existing.qty += qty; } else { currentProposalItems.push({ id, nome: name, preco, qty }); }
    renderProposalItems();
    computeSimulation();
    document.getElementById('prop-product-search').value = '';
    if (hdn) hdn.value = '';
    document.getElementById('prop-product-search').dataset.preco = '';
  });

  document.getElementById('proposal-items-body')?.addEventListener('click', (e) => {
    if (e.target.classList.contains('btn-delete-item')) {
      const idx = parseInt(e.target.dataset.index);
      currentProposalItems.splice(idx, 1);
      renderProposalItems(); computeSimulation();
    }
  });

  // Switches
  ['switch-factor-type','switch-sale-enabled','switch-12m','switch-24m','switch-36m','switch-48m'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', computeSimulation);
  });

  const factorSwitch = document.getElementById('switch-factor-type');
  if (factorSwitch) {
    factorSwitch.addEventListener('change', () => {
      const isImp = factorSwitch.checked;
      const ti  = document.getElementById('label-factor-ti');
      const imp = document.getElementById('label-factor-imp');
      if (ti)  { ti.style.fontWeight  = isImp ? 'normal' : '700'; ti.style.opacity  = isImp ? '0.5' : '1'; }
      if (imp) { imp.style.fontWeight = isImp ? '700' : 'normal';  imp.style.opacity = isImp ? '1' : '0.5'; }
    });
  }

  // Settings
  bind('settings-form', 'submit', handleSettingsSubmit);

  // History
  const histSearch = document.getElementById('history-search');
  if (histSearch) {
    histSearch.addEventListener('input', () => {
      const q = histSearch.value.toLowerCase().trim();
      renderProposalsTable(allProposals.filter(p => p.cliente.toLowerCase().includes(q)));
    });
  }

  document.getElementById('history-table-body')?.addEventListener('click', (e) => {
    const viewBtn = e.target.closest('.btn-view-proposal');
    if (viewBtn) {
      const id = viewBtn.dataset.id;
      const p = allProposals.find(item => item.id === id || String(item.numero) === id);
      if (p) openProposalModal(p);
      return;
    }

    const pdfBtn = e.target.closest('.btn-download-pdf');
    if (pdfBtn) {
      const id = pdfBtn.dataset.id;
      const p = allProposals.find(item => item.id === id || String(item.numero) === id);
      if (p) generateProposalPDF(p);
      return;
    }

    const delBtn = e.target.closest('.btn-delete-item');
    if (delBtn) {
      const id = delBtn.dataset.id;
      const p = allProposals.find(item => item.id === id || String(item.numero) === id);
      if (p && confirm(`Excluir proposta Nº ${p.numero} de "${p.cliente}"?`)) {
        deleteProposal(p.id);
      }
      return;
    }
  });

  // Modal de visualização de proposta
  bind('btn-close-view-modal', 'click', closeProposalModal);
  bind('btn-close-view-modal-footer', 'click', closeProposalModal);
  bind('btn-download-pdf-modal', 'click', () => {
    if (viewingProposal) generateProposalPDF(viewingProposal);
  });

  const viewModal = document.getElementById('modal-view-proposal');
  if (viewModal) {
    viewModal.addEventListener('click', (e) => {
      if (e.target === viewModal) closeProposalModal();
    });
  }
}

// ─── Init ─────────────────────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  loadConfiguredFactors();
  setupEvents();
  renderProposalItems();
  checkSession();
});
